method concatenate(strings: seq<string>) returns (result: string)
    requires strings != null
    ensures |strings| == 0 ==> result == ""
    ensures |strings| > 0 ==> result == concat(strings)
{
    var s := "";
    var i := 0;
    while i < |strings|
        invariant 0 <= i <= |strings|
        invariant result == concat(strings[0..i])
    {
        s := s + strings[i];
        i := i + 1;
    }
    result := s;
}
```

